-- 키이스케이프 공식 포스터 채우기 (출처: https://www.keyescape.com/reservation1.php, 2026-11-13 확인)
-- Supabase → SQL Editor 에 붙여 넣고 Run. 비어 있는 것만 채운다.
select count(*) filter (where coalesce(poster_url,'')<>'') as 포스터있음, count(*) as 전체 from public.catalog where cafe like '키이스케이프%';

